PROGRAM Main
VAR
    State : INT;
    SensorA : REAL := 0.0;
    SensorB : REAL := 0.0;
    MaxDeviation : REAL := 0.5;
    SensorMismatch : BOOL;
    LevelHighHigh : BOOL := FALSE;
    InletValve : BOOL := TRUE;
    MaintenanceMode : BOOL := FALSE;
    JogCommand : BOOL := FALSE;
    Counter : INT := 0;
    Limit : INT := 10;
    SafetyOverride : BOOL := FALSE;
END_VAR
    SensorMismatch := ABS(SensorA - SensorB) > MaxDeviation;
    IF LevelHighHigh THEN
        InletValve := FALSE;
    END_IF;
    CASE State OF
        0 :
            IF NOT MaintenanceMode THEN
                State := 1;
            END_IF;
        1 :
            IF NOT MaintenanceMode THEN
                State := 2;
            END_IF;
        2 :
            IF NOT MaintenanceMode THEN
                State := 0;
            END_IF;
    END_CASE;
    WHILE Counter <= Limit DO
        Counter := Counter + 1;
    END_WHILE;
    IF MaintenanceMode THEN
        IF JogCommand THEN
            InletValve := NOT InletValve;
        END_IF;
    END_IF;
    IF SafetyOverride THEN
        InletValve := FALSE;
    END_IF;
    (* VULN: Maintenance bypass skips level check *)
    IF MaintenanceMode THEN
        LevelHighHigh := FALSE;
    END_IF;
END_PROGRAM
